                .content("""
                    {
                      "frameId": "%s",
                      "mediaType": "DIGITAL",
                      "format": "D6",
                      "environment": "UNDERGROUND",
                      "status": "%s",
                      "location": {
                        "postcode": "W1J 9DZ",
                        "region": "London",
                        "town": "London"
                      },
                      "site": {
                        "siteNumber": "SITE-1"
                      }
                    }
                    """.formatted(frameId, status)))
            .andExpect(status().isCreated());
    }
}

