    private ObjectNode updateRequest(String createRequest) throws Exception {
        ObjectNode request = (ObjectNode) objectMapper.readTree(createRequest);
        request.remove("frameId");
        return request;
    }

    private String createRequest(
        String frameId,
        String status,
        String mediaType,
        String environment,
        String format,
        String region,
        String station,
        String address
    ) {
        return """
            {
              "frameId": "%s",
              "mediaType": "%s",
              "format": "%s",
              "environment": "%s",
              "status": "%s",
              "location": {
                "postcode": "W1J 9DZ",
                "address": "%s",
                "region": "%s",
                "countryCode": "UK",
                "town": "London West End",
                "longitude": -0.14174505,
                "latitude": 51.50604991,
                "distanceToClosestSchool": 637
              },
              "site": {
                "siteNumber": "SITE-1",
                "panelNumber": "01",
                "station": "%s"
              },
              "technical": {
                "numberOfSlots": 6,
                "sizeCode": "D6",
                "pixelHeight": 1200,
                "pixelWidth": 1920
              },
              "commercial": {
                "impactWeight": 0.6027,
                "premium": false
              },
              "integrations": {
                "broadsignFrameId": "BS-%s"
              }
            }
            """.formatted(
                frameId, mediaType, format, environment, status,
                address, region, station, frameId.trim()
            );
    }
